1	// Package command implements a reusable command tree with arbitrary-depth
2	// subcommands and aliases.
3	//
4	// Nodes are created with New and attached to their parent with (*Node).Add.
5	// Execution starts at any node through (*Node).Execute, which descends one
6	// argument at a time, matching only exact, case-sensitive primary names and
7	// aliases; aliases resolve to the canonical primary name reported to the
8	// handler. Plain-text help is generated on demand through
9	// (*Node).WriteHelp; shell completion scripts are generated on demand
10	// through (*Node).WriteCompletion. Neither Execute nor WriteHelp
11	// interprets "--help" or "-h". Apart from the WriteHelp and
12	// WriteCompletion outputs themselves the package never produces help text,
13	// completions, or log output, and it never writes to the stdout/stderr
14	// writers passed to Execute — only node handlers do.
15	package command
16	
17	import (
18		"context"
19		"errors"
20		"fmt"
21		"io"
22		"strings"
23	)
24	
25	// Sentinel errors describing registration and execution failures.
26	//
27	// Callers must use errors.Is rather than direct comparison where the
28	// documentation promises a wrapping error type (ErrInvalidName and
29	// ErrUnknownCommand); the others are returned directly.
30	var (
31		// ErrInvalidName indicates an empty or otherwise illegal primary name
32		// or alias. It is wrapped by *NameError carrying the offending name.
33		ErrInvalidName = errors.New("command: invalid command name")
34	
35		// ErrInvalidCommand is returned when Add receives a nil node (or a node
36		// that cannot legally be attached, such as an ancestor of the parent).
37		ErrInvalidCommand = errors.New("command: invalid command node")
38	
39		// ErrNameConflict indicates a duplicated primary name or alias under
40		// the same parent, including aliases duplicated inside one node. It is
41		// wrapped by *ConflictError carrying the duplicated name.
42		ErrNameConflict = errors.New("command: command name conflict")
43	
44		// ErrAlreadyAttached indicates that Add was called for a node that
45		// already has a parent. It is wrapped by *AttachedError.
46		ErrAlreadyAttached = errors.New("command: command already attached to a parent")
47	
48		// ErrUnknownCommand marks a LookupError produced when an argument
49		// matches neither a child's primary name nor one of its aliases.
50		ErrUnknownCommand = errors.New("command: unknown command")
51	
52		// ErrCommandRequired is returned when arguments run out at a node that
53		// has no handler, so no action can run.
54		ErrCommandRequired = errors.New("command: command required but no argument remained")
55	)
56	
57	// NameError wraps ErrInvalidName and reports the offending primary name or
58	// alias.
59	type NameError struct {
60		// Name is the primary name or alias that failed validation.
61		Name string
62	}
63	
64	func (e *NameError) Error() string {
65		return fmt.Sprintf("command: invalid command name %q", e.Name)
66	}
67	
68	// Unwrap exposes ErrInvalidName for errors.Is and errors.As.
69	func (e *NameError) Unwrap() error { return ErrInvalidName }
70	
71	// ConflictError wraps ErrNameConflict and reports the name that collided
72	// with an already registered primary name or alias.
73	type ConflictError struct {
74		// Name is the primary name or alias that collided.
75		Name string
76	}
77	
78	func (e *ConflictError) Error() string {
79		return fmt.Sprintf("command: command name %q is already registered", e.Name)
80	}
81	
82	// Unwrap exposes ErrNameConflict for errors.Is and errors.As.
83	func (e *ConflictError) Unwrap() error { return ErrNameConflict }
84	
85	// AttachedError wraps ErrAlreadyAttached and reports the node that was
86	// attached for a second time.
87	type AttachedError struct {
88		// Name is the primary name of the node that already has a parent.
89		Name string
90	}
91	
92	func (e *AttachedError) Error() string {
93		return fmt.Sprintf("command: command %q is already attached to a parent", e.Name)
94	}
95	
96	// Unwrap exposes ErrAlreadyAttached for errors.Is and errors.As.
97	func (e *AttachedError) Unwrap() error { return ErrAlreadyAttached }
98	
99	// LookupError wraps ErrUnknownCommand. It is returned when a node with
100	// children is asked to resolve an argument that matches none of them. The
101	// handler is not invoked and nothing is written to the Execute writers.
102	type LookupError struct {
103		// Path holds the canonical primary names resolved before the failure,
104		// starting with the execution root.
105		Path []string
106		// Arg is the argument that could not be resolved.
107		Arg string
108	}
109	
110	func (e *LookupError) Error() string {
111		if len(e.Path) == 0 {
112			return fmt.Sprintf("command: unknown command %q", e.Arg)
113		}
114		return fmt.Sprintf("command: unknown command %q for %q", e.Arg, strings.Join(e.Path, " "))
115	}
116	
117	// Unwrap exposes ErrUnknownCommand for errors.Is and errors.As.
118	func (e *LookupError) Unwrap() error { return ErrUnknownCommand }
119	
120	// HandlerFunc is the action attached to a node.
121	//
122	// path holds the canonical primary names from the execution root to the
123	// matched node; an alias used during resolution is replaced by the child's
124	// primary name. args holds the arguments not consumed by resolution, in
125	// their original order and with their original content. stdout and stderr
126	// are the writers passed to Execute. Whatever error the handler returns is
127	// returned by Execute without wrapping.
128	type HandlerFunc func(path []string, args []string, stdout, stderr io.Writer) error
129	
130	// Node is one command in the tree, identified by a primary name and zero or
131	// more aliases. A node may carry a handler, children, or both.
132	type Node struct {
133		name     string
134		desc     string
135		aliases  []string
136		handler  HandlerFunc
137		parent   *Node
138		children []*Node
139		byName   map[string]*Node
140	}
141	
142	// New creates an unattached node. handler may be nil; the aliases slice is
143	// copied so later caller mutations cannot affect the node. A node is not
144	// validated until it is attached with Add.
145	func New(name, description string, aliases []string, handler HandlerFunc) *Node {
146		return &Node{
147			name:    name,
148			desc:    description,
149			aliases: append([]string(nil), aliases...),
150			handler: handler,
151			byName:  make(map[string]*Node),
152		}
153	}
154	
155	// Name returns the node's primary name.
156	func (n *Node) Name() string { return n.name }
157	
158	// Description returns the node's description.
159	func (n *Node) Description() string { return n.desc }
160	
161	// Aliases returns a copy of the node's aliases in registration order.
162	func (n *Node) Aliases() []string { return append([]string(nil), n.aliases...) }
163	
164	// validName reports whether s is a legal primary name or alias: non-empty,
165	// restricted to ASCII letters, digits, hyphens and underscores, and not
166	// starting with a hyphen.
167	func validName(s string) bool {
168		if s == "" || s[0] == '-' {
169			return false
170		}
171		for i := 0; i < len(s); i++ {
172			switch c := s[i]; {
173			case c >= 'a' && c <= 'z':
174			case c >= 'A' && c <= 'Z':
175			case c >= '0' && c <= '9':
176			case c == '-' || c == '_':
177			default:
178				return false
179			}
180		}
181		return true
182	}
183	
184	// validateOwnNames checks the primary name and aliases of an unattached
185	// candidate node: every name must be valid, and no name may repeat.
186	func validateOwnNames(child *Node) error {
187		if !validName(child.name) {
188			return &NameError{Name: child.name}
189		}
190		seen := make(map[string]struct{}, len(child.aliases)+1)
191		seen[child.name] = struct{}{}
192		for _, alias := range child.aliases {
193			if !validName(alias) {
194				return &NameError{Name: alias}
195			}
196			if _, dup := seen[alias]; dup {
197				return &ConflictError{Name: alias}
198			}
199			seen[alias] = struct{}{}
200		}
201		return nil
202	}
203	
204	// Add attaches child to n. The tree is only modified after every check has
205	// succeeded, so a failed Add leaves the tree untouched. On success children
206	// remain in the order in which they were added.
207	func (n *Node) Add(child *Node) error {
208		if child == nil {
209			return ErrInvalidCommand
210		}
211		if err := validateOwnNames(child); err != nil {
212			return err
213		}
214		if child.parent != nil {
215			return &AttachedError{Name: child.name}
216		}
217		// Attaching an ancestor (including n itself) would create a cycle and
218		// corrupt traversal; treat it as an invalid node.
219		for ancestor := n; ancestor != nil; ancestor = ancestor.parent {
220			if ancestor == child {
221				return fmt.Errorf("command: cannot attach %q into its own subtree: %w", child.name, ErrInvalidCommand)
222			}
223		}
224		keys := make([]string, 0, len(child.aliases)+1)
225		keys = append(keys, child.name)
226		keys = append(keys, child.aliases...)
227		for _, key := range keys {
228			if _, exists := n.byName[key]; exists {
229				return &ConflictError{Name: key}
230			}
231		}
232	
233		for _, key := range keys {
234			n.byName[key] = child
235		}
236		n.children = append(n.children, child)
237		child.parent = n
238		return nil
239	}
240	
241	// Execute resolves args against the tree rooted at n and runs the matched
242	// handler. While the current node has children, the next argument selects a
243	// child by exact primary name or alias; a miss yields a *LookupError
244	// wrapping ErrUnknownCommand. Once a node without
245	// children is reached, all remaining arguments go to its handler. A node
246	// with children but no next argument runs its own handler when present and
247	// returns ErrCommandRequired otherwise.
248	//
249	// If ctx is already canceled or past its deadline before resolution starts,
250	// ctx.Err() is returned directly. Handler errors are returned unchanged and
251	// the package itself never writes to stdout or stderr.
252	func (n *Node) Execute(ctx context.Context, args []string, stdout, stderr io.Writer) error {
253		if err := ctx.Err(); err != nil {
254			return err
255		}
256	
257		current := n
258		path := []string{current.name}
259	
260		for len(current.children) > 0 {
261			if len(args) == 0 {
262				if current.handler != nil {
263					return current.handler(path, args, stdout, stderr)
264				}
265				return ErrCommandRequired
266			}
267			next, ok := current.byName[args[0]]
268			if !ok {
269				resolved := make([]string, len(path))
270				copy(resolved, path)
271				return &LookupError{Path: resolved, Arg: args[0]}
272			}
273			current = next
274			path = append(path, current.name)
275			args = args[1:]
276		}
277	
278		if current.handler == nil {
279			return ErrCommandRequired
280		}
281		return current.handler(path, args, stdout, stderr)
282	}
