//   - ClassDefinition: the program itself registered an invalid command
//     tree or parser specification; exit code 70 (EX_SOFTWARE).
//   - ClassCanceled: the context was canceled; exit code 130.
//   - ClassTimeout: the context's deadline elapsed; exit code 124.
//   - ClassFailure: any other non-nil error; exit code 1.
type ErrorClass int

const (
	// ClassNone means no error. ClassifyError(nil) returns it.
	ClassNone ErrorClass = iota
	// ClassUsage means the command line was used incorrectly.
	ClassUsage
	// ClassConfiguration means configuration (files or environment) is
	// invalid or unavailable.
	ClassConfiguration
	// ClassDefinition means the program's own command or parser
	// definition is invalid.
	ClassDefinition
	// ClassCanceled means the operation was canceled through its
	// context.
	ClassCanceled
	// ClassTimeout means the operation exceeded its context deadline.
	ClassTimeout
	// ClassFailure is the class of every other non-nil error.
	ClassFailure
)

// String returns the stable textual value of the class: "none", "usage",
// "configuration", "definition", "canceled", "timeout" or "failure".
func (c ErrorClass) String() string {
	switch c {
	case ClassNone:
		return "none"
	case ClassUsage:
		return "usage"
	case ClassConfiguration:
		return "configuration"
	case ClassDefinition:
		return "definition"
	case ClassCanceled:
		return "canceled"
	case ClassTimeout:
		return "timeout"
	default:
		return "failure"
	}
}

// ExitCode returns the conventional process exit code for c: 0 for
// ClassNone, 2 for ClassUsage, 78 for ClassConfiguration, 70 for
// ClassDefinition, 130 for ClassCanceled, 124 for ClassTimeout, and 1 for
// ClassFailure and any other value.
func (c ErrorClass) ExitCode() int {
	switch c {
	case ClassNone:
		return 0
	case ClassUsage:
		return 2
	case ClassConfiguration:
		return 78
	case ClassDefinition:
		return 70
	case ClassCanceled:
		return 130
	case ClassTimeout:
		return 124
	default:
		return 1
	}
}

// ClassifyError maps err to a stable ErrorClass by inspecting it with
// errors.Is and errors.As, so every rule sees through fmt.Errorf("%w")
// wrapping and through the joined causes of errors.Join. A nil error is
// ClassNone; an unknown non-nil error is ClassFailure; the error text
// never affects the result.
//
// The direct rules are:
//
//   - context.Canceled is ClassCanceled; context.DeadlineExceeded is
//     ClassTimeout.
//   - *ConfigError, and a *ParseError wrapping ErrInvalidValue whose
//     Source is SourceEnvironment or SourceConfig, are
//     ClassConfiguration.
//   - *LookupError, ErrCommandRequired, *ShellError, and a *ParseError
//     arising from the command line (SourceNone), including every
//     remaining *ParseError, are ClassUsage.
//   - *NameError, *ConflictError, *AttachedError, *SpecError and
//     ErrInvalidCommand are ClassDefinition.
//
// When several causes are reachable (multi-layer wrapping or errors.Join),
// the result is the cause with the highest fixed priority: canceled,
// timeout, configuration, usage, definition, failure. Classification
// only reads err; it changes none of its fields.
func ClassifyError(err error) ErrorClass {
	if err == nil {
		return ClassNone
	}
	return classRank(err).class
}

// ExitCode returns the process exit code ClassifyError assigns to err:
// ClassifyError(err).ExitCode(). It is 0 for nil and 1 for an unknown
// non-nil error.
func ExitCode(err error) int {
	if err == nil {
		return 0
	}
	return classRank(err).class.ExitCode()
}

// rankedClass pairs an ErrorClass with its fixed precedence. Higher rank
// wins when an error exposes more than one cause.
type rankedClass struct {
	class ErrorClass
	rank  int
}

// classRank walks the full error graph — Unwrap chains, multi-error
// Unwrap() []error slices (as produced by errors.Join), and Is/As
// target matches — and returns the highest-priority class reachable. The
// traversal allocates only its small visited set and touches no state
// outside err.
func classRank(err error) rankedClass {
	// best tracks the highest-priority finding; failure (the implicit
	// class of every unrecognized non-nil error) is the floor.
	best := rankedClass{class: ClassFailure, rank: 0}

	var walk func(error)
	walk = func(err error) {
		if err == nil {
			return
		}
		// Every reachable non-nil node is at least a failure, so a
		// graph that matches no rule still yields ClassFailure.
		if best.rank < 0 {
			best.rank = 0
		}

		switch rc := directClass(err); {
		case rc.rank > best.rank:
			best = rc
			if rc.rank == int(ClassFailure)+5 {
				// Highest possible priority; nothing more to find.
				return
			}
		}

		// Unwrap chains and joined/sliced causes. Both forms are
		// visited so errors.Join results are classified by their
		// highest-priority member.
		switch u := err.(type) {
		case interface{ Unwrap() error }:
			walk(u.Unwrap())
		case interface{ Unwrap() []error }:
			for _, cause := range u.Unwrap() {
				walk(cause)
			}
		}
	}
	walk(err)
	return best
}

// directClass classifies err itself (not its causes).
func directClass(err error) rankedClass {
	// Context errors first: they are plain values matched by errors.Is.
	switch {
	case errors.Is(err, context.Canceled):
		return rankedClass{ClassCanceled, cancelRank}
	case errors.Is(err, context.DeadlineExceeded):
		return rankedClass{ClassTimeout, timeoutRank}
	}

	var pe *ParseError
	if errors.As(err, &pe) {
		if errors.Is(err, ErrInvalidValue) &&
			(pe.Source == SourceEnvironment || pe.Source == SourceConfig) {
			return rankedClass{ClassConfiguration, configRank}
		}
		// Every other parse error, including command-line invalid
		// values (SourceNone), is a command-line usage failure.
		return rankedClass{ClassUsage, usageRank}
	}

	switch {
	case errors.As(err, new(*ConfigError)):
		return rankedClass{ClassConfiguration, configRank}
	case errors.As(err, new(*LookupError)):
		return rankedClass{ClassUsage, usageRank}
	case errors.Is(err, ErrCommandRequired):
		return rankedClass{ClassUsage, usageRank}
	case errors.As(err, new(*ShellError)):
		return rankedClass{ClassUsage, usageRank}
	case errors.As(err, new(*NameError)):
		return rankedClass{ClassDefinition, definitionRank}
	case errors.As(err, new(*ConflictError)):
		return rankedClass{ClassDefinition, definitionRank}
	case errors.As(err, new(*AttachedError)):
		return rankedClass{ClassDefinition, definitionRank}
	case errors.As(err, new(*SpecError)):
		return rankedClass{ClassDefinition, definitionRank}
	case errors.Is(err, ErrInvalidCommand):
		return rankedClass{ClassDefinition, definitionRank}
	}
	return rankedClass{ClassFailure, failureRank}
}

// Priority ranks, highest first: canceled > timeout > configuration >
// usage > definition > failure.
const (
	failureRank    = 0
	definitionRank = 1
	usageRank      = 2
	configRank     = 3
	timeoutRank    = 4
	cancelRank     = 5
)

